-- CI production replay journal seed — marks all production-applied scripts as already run.
-- DO NOT EDIT BY HAND. Regenerate with: bash .github/scripts/dump-replay-schema.sh --env production

CREATE TABLE IF NOT EXISTS schemaversions (
  schemaversionid SERIAL PRIMARY KEY,
  scriptname VARCHAR(512) NOT NULL,
  applied TIMESTAMPTZ NOT NULL DEFAULT now()
);


SELECT 'replay-prod journal seed applied (' || count(*) || ' scripts)' AS status FROM schemaversions;
